-- v9: native Interactive Grid custom DML; use the submitted primary key DATE_KEY.
-- Explicitly submit the hidden ROW_VERSION for the custom concurrency check.
-- App 172 / Page 35. Binders: dates in rows, work centers in columns.
-- Replaces page 35. Back up the current page before running.
-- Run in SQL Workshop > SQL Scripts > Upload > Run, in the original workspace.
-- Work centers are discovered at installation time; rerun to add/remove columns.
-- PLAN_ID must be generated by the existing identity/default/trigger.
-- No tables, sequences or business data are created or deleted by this installer.
set define off verify off feedback off
whenever sqlerror exit sql.sqlcode rollback

declare
    type t_wc is table of TJP_ENG04_MASTER%rowtype;
    l_wc t_wc;
    l_source varchar2(32767);
    l_inner varchar2(32767);
    l_hash varchar2(32767) := '''v1''';
    l_dml varchar2(32767);
    l_col varchar2(30);
    l_id number;
    l_duplicates number;
    l_cursor integer;
    function lit(p_value varchar2) return varchar2 is
    begin return dbms_assert.enquote_literal(p_value); end;
    procedure add_column(p_id number, p_name varchar2, p_heading varchar2,
                         p_type varchar2, p_item varchar2, p_seq number,
                         p_pk boolean default false, p_query boolean default true) is
    begin
        wwv_flow_imp_page.create_region_column(
            p_id=>wwv_flow_imp.id(p_id), p_name=>p_name,
            p_source_type=>'DB_COLUMN', p_source_expression=>p_name,
            p_data_type=>p_type, p_session_state_data_type=>'VARCHAR2',
            p_is_query_only=>p_query, p_item_type=>p_item,
            -- Hidden non-key values must be available to the row DML process.
            p_attribute_01=>case when p_item='NATIVE_HIDDEN'
                                 then case when p_pk then 'Y' else 'N' end
                                 else null end,
            p_heading=>p_heading, p_display_sequence=>p_seq,
            p_is_primary_key=>p_pk, p_is_required=>false,
            p_enable_filter=>p_item <> 'NATIVE_HIDDEN',
            p_filter_lov_type=>'NONE', p_enable_sort_group=>true,
            p_enable_hide=>true, p_include_in_export=>p_item <> 'NATIVE_HIDDEN');
    end;
begin
    select * bulk collect into l_wc
    from TJP_ENG04_MASTER
    where TABLEID='ENG04' and FIELDID='WORK_CENTER'
      and ACTIVE='Y' and PARENT1='Binders'
    order by PARENT2, LISTVALUE, LISTID;
    if l_wc.count=0 then
        raise_application_error(-20001,'No active Binders work centers found. Page not replaced.');
    end if;
    if l_wc.count>60 then
        raise_application_error(-20002,'More than 60 work centers: review grid width before installation.');
    end if;
    select count(*) into l_duplicates from (
        select p.DATE_KEY,p.LISTID
        from TJP_ENG04_PLAN p
        where exists (select 1 from TJP_ENG04_MASTER m
                      where m.LISTID=p.LISTID and m.TABLEID='ENG04'
                        and m.FIELDID='WORK_CENTER' and m.ACTIVE='Y'
                        and m.PARENT1='Binders')
        group by p.DATE_KEY,p.LISTID having count(*)>1
    );
    if l_duplicates>0 then
        raise_application_error(-20003,'Duplicate DATE_KEY/LISTID in plan. Resolve before installation.');
    end if;
    for i in 1..l_wc.count loop
        for j in 1..i-1 loop
            if l_wc(i).LISTID=l_wc(j).LISTID then
                raise_application_error(-20004,'Duplicate LISTID in active Binders master.');
            end if;
        end loop;
    end loop;
    l_inner := 'select c.DATE_KEY,c.DATE_DIM,c.DAY_WEEK_PLANNING,c.WEEK_PLANNING,c.YEAR,c.COMMENT_PLANNING,c.PLANNER_COMMENTS';
    for i in 1..l_wc.count loop
        l_col := 'Q'||to_char(i,'FM000');
        l_inner := l_inner||', (select p.CANTIDAD from TJP_ENG04_PLAN p where p.DATE_KEY=c.DATE_KEY and p.LISTID='||lit(l_wc(i).LISTID)||') '||l_col;
        l_hash := l_hash||'||''|''||nvl(to_char(x.'||l_col||',''TM9'',''NLS_NUMERIC_CHARACTERS=''''.,''''''),''#'')';
    end loop;
    l_inner := l_inner||' from TJP18_DIM_CALENDARIO c where c.DATE_DIM between trunc(sysdate)-7 and trunc(sysdate)+60';
    l_source := 'select x.*,rawtohex(standard_hash('||l_hash||',''SHA256'')) ROW_VERSION from ('||l_inner||') x';
    l_dml := 'declare l_key number; l_version varchar2(64); begin
if :APEX$ROW_STATUS is null or :APEX$ROW_STATUS <> ''U'' then raise_application_error(-20010,''Solo se permite editar cantidades.''); end if;
if :DATE_KEY is null then
raise_application_error(-20012,''No se recibio DATE_KEY de la fila. No se guardo ninguna cantidad.''); end if;
begin
select DATE_KEY into l_key from TJP18_DIM_CALENDARIO where DATE_KEY=:DATE_KEY for update;
exception when no_data_found then
raise_application_error(-20014,''La fecha no existe en TJP18_DIM_CALENDARIO. DATE_KEY=''||:DATE_KEY);
end;
select ROW_VERSION into l_version from ('||l_source||') where DATE_KEY=:DATE_KEY;
if :ROW_VERSION is null or l_version <> :ROW_VERSION then
raise_application_error(-20011,''Otra sesion modifico las cantidades de esta fecha. Refresca la pagina antes de guardar.''); end if;';
    for i in 1..l_wc.count loop
        l_col := 'Q'||to_char(i,'FM000');
        l_dml := l_dml||chr(10)||'merge into TJP_ENG04_PLAN p using (select :DATE_KEY DATE_KEY,'||lit(l_wc(i).LISTID)||' LISTID, :'||l_col||' CANTIDAD from dual) s
on (p.DATE_KEY=s.DATE_KEY and p.LISTID=s.LISTID)
when matched then update set p.CANTIDAD=s.CANTIDAD
where decode(p.CANTIDAD,s.CANTIDAD,0,1)=1
when not matched then insert (DATE_KEY,LISTID,CANTIDAD) values (s.DATE_KEY,s.LISTID,s.CANTIDAD) where s.CANTIDAD is not null;';
    end loop;
    l_dml := l_dml||chr(10)||'select ROW_VERSION into :ROW_VERSION from ('||l_source||') where DATE_KEY=:DATE_KEY; end;';
    -- Validate generated SQL and row process before replacing the page.
    l_cursor := dbms_sql.open_cursor;
    begin
        dbms_sql.parse(l_cursor,l_source,dbms_sql.native);
        dbms_sql.parse(l_cursor,l_dml,dbms_sql.native);
        dbms_sql.close_cursor(l_cursor);
    exception when others then
        if dbms_sql.is_open(l_cursor) then dbms_sql.close_cursor(l_cursor); end if;
        raise;
    end;
    -- Import context matches the supplied original page export.
    wwv_flow_imp.import_begin(
        p_version_yyyy_mm_dd=>'2026.03.30',p_release=>'26.1.5',
        p_default_workspace_id=>7655586262555210,
        p_default_application_id=>172,
        p_default_id_offset=>133715796712875278,
        p_default_owner=>'WKSP_AVERYWORKSPACE');
    wwv_flow_imp_page.remove_page(p_flow_id=>wwv_flow.g_flow_id,p_page_id=>35);
    wwv_flow_imp_page.create_page(p_id=>35,p_name=>'PLANNING',p_alias=>'PLANNING',
        p_step_title=>'PLANNING',p_autocomplete_on_off=>'OFF',
        p_step_template=>4073832297226169690,p_page_template_options=>'#DEFAULT#',p_protection_level=>'C');
    wwv_flow_imp_page.create_page_plug(
        p_id=>wwv_flow_imp.id(30378326274758815),p_plug_name=>'Binders - Planning',
        p_static_id=>'binders_planning',p_region_template_options=>'#DEFAULT#',
        p_plug_template=>2102002977963900996,p_plug_display_sequence=>10,
        p_query_type=>'SQL',p_plug_source=>l_source,p_plug_source_type=>'NATIVE_IG');
    add_column(30379881606758830,'DATE_KEY','Date Key','NUMBER','NATIVE_HIDDEN',10,true,false);
    add_column(30378553447758817,'DATE_DIM','Date Dim','DATE','NATIVE_DISPLAY_ONLY',20);
    add_column(30378660430758818,'DAY_WEEK_PLANNING','Day Week Planning','VARCHAR2','NATIVE_DISPLAY_ONLY',30);
    add_column(30378763420758819,'WEEK_PLANNING','Week Planning','NUMBER','NATIVE_DISPLAY_ONLY',40);
    add_column(30380068033758832,'YEAR','Year','NUMBER','NATIVE_DISPLAY_ONLY',50);
    add_column(30378867916758820,'COMMENT_PLANNING','Comment Planning','VARCHAR2','NATIVE_DISPLAY_ONLY',60);
    add_column(30378948482758821,'PLANNER_COMMENTS','Planner Comments','VARCHAR2','NATIVE_DISPLAY_ONLY',70);
    add_column(30380168033758833,'ROW_VERSION','Row Version','VARCHAR2','NATIVE_HIDDEN',80,false,false);
    for i in 1..l_wc.count loop
        add_column(30381000000000000+i,'Q'||to_char(i,'FM000'),
            l_wc(i).LISTVALUE,'NUMBER','NATIVE_NUMBER_FIELD',100+i,false,false);
    end loop;
    wwv_flow_imp_page.create_interactive_grid(
        p_id=>wwv_flow_imp.id(30378451616758816),p_internal_uid=>30378451616758816,
        p_is_editable=>true,p_edit_operations=>'u',p_lost_update_check_type=>'VALUES',
        p_add_row_if_empty=>false,p_lazy_loading=>false,p_requires_filter=>false,
        p_select_first_row=>true,p_fixed_row_height=>true,p_pagination_type=>'SET',
        p_show_total_row_count=>true,p_show_toolbar=>true,
        p_enable_save_public_report=>false,p_enable_subscriptions=>false,
        p_enable_flashback=>false,p_define_chart_view=>false,p_enable_download=>true,
        p_download_formats=>'CSV:HTML:XLSX:PDF',p_enable_mail_download=>false,
        p_fixed_header=>'PAGE',p_show_icon_view=>false,p_show_detail_view=>false);
    wwv_flow_imp_page.create_ig_report(
        p_id=>wwv_flow_imp.id(31201124331901754),
        p_interactive_grid_id=>wwv_flow_imp.id(30378451616758816),
        p_static_id=>'primary',p_type=>'PRIMARY',p_default_view=>'GRID',
        p_show_row_number=>false,p_settings_area_expanded=>true);
    wwv_flow_imp_page.create_ig_report_view(
        p_id=>wwv_flow_imp.id(31201231276901755),
        p_report_id=>wwv_flow_imp.id(31201124331901754),
        p_view_type=>'GRID',p_stretch_columns=>false,
        p_srv_exclude_null_values=>false,p_srv_only_display_columns=>true,p_edit_mode=>true);
    wwv_flow_imp_page.create_ig_report_column(
        p_id=>wwv_flow_imp.id(31221900000000001),
        p_view_id=>wwv_flow_imp.id(31201231276901755),p_display_seq=>90,
        p_column_id=>wwv_flow_imp.id(30379881606758830),
        p_is_visible=>false,p_is_frozen=>false);
    for i in 1..7 loop
        l_id := case i when 1 then 30378553447758817 when 2 then 30378660430758818
            when 3 then 30378763420758819 when 4 then 30380068033758832
            when 5 then 30378867916758820 when 6 then 30378948482758821
            when 7 then 30380168033758833 end;
        wwv_flow_imp_page.create_ig_report_column(
            p_id=>wwv_flow_imp.id(31222000000000000+i),
            p_view_id=>wwv_flow_imp.id(31201231276901755),p_display_seq=>i,
            p_column_id=>wwv_flow_imp.id(l_id),p_is_visible=>i<7,p_is_frozen=>i=1);
    end loop;
    for i in 1..l_wc.count loop
        wwv_flow_imp_page.create_ig_report_column(
            p_id=>wwv_flow_imp.id(31223000000000000+i),
            p_view_id=>wwv_flow_imp.id(31201231276901755),p_display_seq=>10+i,
            p_column_id=>wwv_flow_imp.id(30381000000000000+i),
            p_is_visible=>true,p_is_frozen=>false);
    end loop;
    -- Native IG DML binds the submitted model columns for each changed row.
    -- Custom PL/SQL handles both locking and optimistic concurrency itself.
    wwv_flow_imp_page.create_page_process(
        p_id=>wwv_flow_imp.id(30379658510758828),
        p_process_sequence=>10,
        p_process_point=>'AFTER_SUBMIT',
        p_region_id=>wwv_flow_imp.id(30378326274758815),
        p_process_type=>'NATIVE_IG_DML',
        p_process_name=>'Binders - Save Quantities',
        p_attribute_01=>'PLSQL_CODE',
        p_attribute_04=>l_dml,
        p_attribute_05=>'N',
        p_attribute_06=>'N',
        p_attribute_08=>'Y',
        p_error_display_location=>'INLINE_IN_NOTIFICATION',
        p_internal_uid=>30379658510758828);
    wwv_flow_imp.import_end(p_auto_install_sup_obj=>false);
    commit;
exception when others then rollback; raise;
end;
/
set verify on feedback on define on
